        0.0529148f, 0.0162172f, -0.0161816f, -0.0165183f, -0.0931464f, 0.0310183f, -0.0106235f, -0.0057419f,
    )

    val B3 = floatArrayOf(
        0.0005271f, -0.0097184f, 0.0123849f,
    )

    /** One 3x3 convolution with zero padding, optionally followed by ReLU. */
    private fun conv3(src: FloatArray, cin: Int, h: Int, w: Int, wt: FloatArray, bias: FloatArray, cout: Int, relu: Boolean): FloatArray {
        val dst = FloatArray(cout * h * w)
        for (o in 0 until cout) {
            val base = o * h * w
            for (i in 0 until h * w) dst[base + i] = bias[o]
            for (ci in 0 until cin) for (ky in 0..2) for (kx in 0..2) {
                val k = wt[((o * cin + ci) * 3 + ky) * 3 + kx]
                val dy = ky - 1
                val dx = kx - 1
                for (y in 0 until h) {
                    val sy = y + dy
                    if (sy < 0 || sy >= h) continue
                    for (x in 0 until w) {
                        val sx = x + dx
                        if (sx < 0 || sx >= w) continue
                        dst[base + y * w + x] += k * src[(ci * h + sy) * w + sx]
                    }
                }
            }
            if (relu) for (i in 0 until h * w) if (dst[base + i] < 0f) dst[base + i] = 0f
        }
        return dst
    }

    /** Runs the model on one picture patch (3 planes, h rows, w columns). The result has the same shape. */
    fun enhancePatch(x: FloatArray, h: Int, w: Int): FloatArray {
        val a1 = conv3(x, 3, h, w, W1, B1, C, true)
        val a2 = conv3(a1, C, h, w, W2, B2, C, true)
        val r = conv3(a2, C, h, w, W3, B3, 3, false)
        for (i in r.indices) r[i] = (r[i] + x[i]).coerceIn(0f, 1f)
        return r
    }
}
